import json

# Read package.json to understand project structure
try:
    with open('package.json', 'r') as f:
        package_data = json.load(f)
    print("Project name:", package_data.get('name', 'Unknown'))
    print("Version:", package_data.get('version', 'Unknown'))
    print("Description:", package_data.get('description', 'No description'))
    print("Dependencies:", list(package_data.get('dependencies', {}).keys()))
