{"language":"py","code":"# Let's look at the git status to understand what we're working with
import subprocess

try:
    result = subprocess.run(['git', 'status', '--porcelain'], capture_output=True, text=True)
    print("Git status:")
    print(result.stdout)
except Exception as e:
    print(f"Error running git status: {e}")","title":"Git status check"}

{"language":"py","code":"# Let's examine the current git branch and commit
import subprocess

try:
    result = subprocess.run(['git', 'branch', '--show-current'], capture_output=True, text=True)
    print("Current branch:", result.stdout.strip())

    result = subprocess.run(['git', 'log', '-1', '--oneline'], capture_output=True, text=True)
    print("Last commit:", result.stdout.strip())
except Exception as e:
    print(f"Error getting git info: {e}")","title":"Git branch and commit info"}
